const raw = $input.first().json || {};
const isWebhook = !!(raw.body && typeof raw.body === 'object' && raw.headers);
const src = isWebhook ? raw.body : raw;
const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
return [{ json: {
  channel: isWebhook ? 'webhook' : 'tool',
  task_id: s(src.task_id) || ('TASK-' + Date.now()),
  from_agent: s(src.from_agent) || 'careos_orchestrator',
  patient_id: s(src.patient_id).toUpperCase(),
  user_role: s(src.user_role).toLowerCase(),
  user_ref: s(src.user_ref),
  request_text: s(src.request_text)
} }];

const req = $('Normalize Request').first().json;
const clean = (name, key) => $(name).all().map(i => i.json).filter(r => r && r[key]);
const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const low = (v) => s(v).toLowerCase();
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

const out = { req: req, status: 'error', reason: '', write: false };
const finish = () => [{ json: out }];

if (!req.patient_id) { out.reason = 'patient_id required'; return finish(); }
const allowed = ['patient', 'doctor', 'nurse', 'admin', 'operations'];
if (allowed.indexOf(req.user_role) === -1) { out.status = 'forbidden'; out.reason = 'role ' + (req.user_role || '(none)') + ' may not run discharge analysis'; return finish(); }
if (req.user_role === 'patient' && req.user_ref.toUpperCase() !== req.patient_id) { out.status = 'forbidden'; out.reason = 'patients may only view their own discharge status'; return finish(); }

const patient = clean('Get Patient', 'patient_id')[0];
if (!patient) { out.status = 'not_found'; out.reason = 'patient ' + req.patient_id + ' not found'; return finish(); }
const doctor = clean('Get Attending Doctor', 'doctor_id')[0];
const journey = clean('Journey Agent', 'event_id');
const dis = clean('Discharge Agent', 'patient_id')[0];
const bills = clean('Billing Agent', 'bill_id');
const auths = clean('Insurance Agent', 'auth_id');
const rxs = clean('Pharmacy Agent', 'rx_id');
const diags = clean('Diagnostics Agent', 'order_id');
const bed = clean('Bed Agent', 'resource_id')[0];
const openBn = clean('Get Open Bottlenecks', 'bottleneck_id').filter(b => low(b.status) === 'open');

const docLabel = doctor ? (doctor.doctor_name + ' (' + doctor.doctor_id + ')') : (patient.attending_doctor_id || 'Attending doctor');
const unavailable = [];
const agents = [];
const mark = (agent, system, ok, note) => { agents.push({ agent: agent, system: system, status: ok ? 'success' : 'unavailable', note: note }); if (!ok) unavailable.push(agent); };

// Journey
const openSteps = journey.filter(e => ['pending', 'in_progress', 'blocked'].indexOf(low(e.status)) !== -1).map(e => e.event_type + ':' + low(e.status));
mark('journey_agent', 'careos_data_layer', journey.length > 0, journey.length ? (journey.length + ' events; open ' + (openSteps.join(', ') || 'none')) : 'no journey events');
// Discharge checklist
mark('discharge_agent', 'careos_data_layer', !!dis, dis ? 'checklist found' : 'no discharge checklist');
// Diagnostics
const pendingDx = diags.filter(d => low(d.review_status) === 'pending' || ['ordered', 'scheduled', 'in_progress'].indexOf(low(d.status)) !== -1);
mark('diagnostics_agent', 'careos_data_layer', true, diags.length + ' orders, ' + pendingDx.length + ' pending');
// Billing
const outstanding = bills.reduce((a, b) => a + (Number(b.outstanding_amount) || 0), 0);
mark('billing_agent', 'suvarna_erp', bills.length > 0 || !!dis, bills.length ? ('outstanding INR ' + outstanding) : 'no bill in ERP');
// Insurance
const auth = auths[0];
mark('insurance_agent', 'suvarna_erp', auths.length > 0 || !!dis, auth ? (auth.insurer + ' ' + auth.auth_status) : 'no authorization record');
// Pharmacy
const rx = rxs.find(r => r.discharge_meds === true || low(r.discharge_meds) === 'true') || rxs[0];
mark('pharmacy_agent', 'suvarna_erp', rxs.length > 0 || !!dis, rx ? (rx.rx_id + ' ' + rx.rx_status + '/' + rx.stock_status) : 'no prescription');
// Bed
mark('bed_agent', 'careos_data_layer', !!bed, bed ? (bed.resource_id + ' ' + bed.status) : 'bed record unavailable');

// Clearances
const cl = {};
const pendingReview = diags.filter(d => low(d.review_status) === 'pending');
const docCl = dis ? low(dis.doctor_clearance) : '';
if (!dis && !diags.length) cl.clinical = 'unavailable';
else if (pendingReview.length) cl.clinical = 'pending - doctor review of ' + pendingReview.map(d => d.order_id + ' ' + d.test_name).join(', ');
else if (docCl && docCl !== 'complete') cl.clinical = 'pending - doctor clearance ' + docCl;
else if (!dis) cl.clinical = 'unavailable';
else cl.clinical = 'complete';

cl.diagnostics = pendingDx.length ? ('pending - ' + pendingDx.map(d => d.order_id + ' ' + d.test_name + ' (' + (low(d.review_status) === 'pending' ? 'review pending' : low(d.status)) + ')').join(', ')) : (diags.length ? 'complete' : 'no orders');

if (rx) {
  const rs = low(rx.rx_status), st = low(rx.stock_status);
  cl.pharmacy = (rs === 'ready' || rs === 'dispensed') && st !== 'out_of_stock' ? 'ready' : ('pending - ' + rx.rx_id + ' ' + rs + (st === 'out_of_stock' ? ' (out of stock)' : ''));
} else if (dis) cl.pharmacy = low(dis.pharmacy_clearance) === 'ready' ? 'ready' : ('pending - ' + low(dis.pharmacy_clearance));
else cl.pharmacy = 'unavailable';

if (bills.length) {
  const b = bills[0];
  const bc = low(b.clearance_status);
  cl.billing = (outstanding > 0 || (bc && bc !== 'cleared')) ? ('pending - outstanding INR ' + outstanding + (b.blocker ? ' (' + b.blocker + ')' : '')) : 'cleared';
} else if (dis) cl.billing = low(dis.billing_clearance) === 'cleared' ? 'cleared' : ('pending - ' + low(dis.billing_clearance));
else cl.billing = 'unavailable';

if (auth) {
  const as = low(auth.auth_status);
  cl.insurance = (as === 'approved' || as === 'not_applicable') ? as : ('pending - ' + auth.insurer + ' ' + auth.auth_id + ' ' + as + (s(auth.pending_documents) ? '; documents pending: ' + auth.pending_documents : ''));
} else if (dis) { const ic = low(dis.insurance_clearance); cl.insurance = (ic === 'approved' || ic === 'not_applicable') ? ic : ('pending - ' + ic); }
else cl.insurance = 'unavailable';

cl.summary = dis ? (low(dis.summary_status) === 'complete' ? 'complete' : ('pending - ' + low(dis.summary_status))) : 'unavailable';
cl.transport = dis ? low(dis.transport_status) : 'unavailable';
cl.bed = bed ? (bed.status + (bed.next_available ? ' (release planned ' + bed.next_available + ')' : '')) : (dis ? low(dis.bed_release_status) : 'unavailable');

// Blockers in priority order
const blockers = [];
const add = (key, label, owner, action) => blockers.push({ key: key, label: label, owner: owner, action: action });
if (cl.clinical.indexOf('pending') === 0) add('clinical', pendingReview.length ? 'Doctor review pending' : 'Clinical clearance pending', docLabel, pendingReview.length ? ('Ask ' + docLabel + ' to review ' + pendingReview.map(d => d.order_id + ' ' + d.test_name).join(', ') + ' and record clinical clearance') : ('Ask ' + docLabel + ' to complete clinical clearance'));
if (cl.insurance.indexOf('pending') === 0) add('insurance', 'Insurance authorization pending', 'Insurance Desk', auth ? ('Insurance Desk to follow up with ' + auth.insurer + ' on ' + auth.auth_id + (s(auth.pending_documents) ? ' and submit: ' + auth.pending_documents : '')) : 'Insurance Desk to confirm authorization status');
if (cl.billing.indexOf('pending') === 0) add('billing', 'Billing clearance pending', 'Billing Desk', 'Billing Desk to settle outstanding INR ' + outstanding + ' and issue final clearance');
if (cl.pharmacy.indexOf('pending') === 0) add('pharmacy', 'Discharge medication pending', 'Pharmacy', 'Pharmacy to prepare discharge medicines');
if (cl.summary.indexOf('pending') === 0) add('summary', 'Discharge summary pending', docLabel, docLabel + ' to finalise the discharge summary');
if (['delayed', 'unavailable_vehicle', 'failed'].indexOf(cl.transport) !== -1) add('transport', 'Transport delayed', 'Transport Desk', 'Transport Desk to arrange vehicle');

const primary = blockers[0] || null;
const plannedMs = dis && dis.planned_discharge_at ? new Date(dis.planned_discharge_at).getTime() : null;
const minsPast = plannedMs ? Math.round((nowMs - plannedMs) / 60000) : null;
const existing = primary ? openBn[0] : null;
const ownerRef = primary ? (primary.key === 'clinical' || primary.key === 'summary' ? (doctor ? doctor.doctor_id : patient.attending_doctor_id) : primary.owner) : '';
const bnId = primary ? (existing ? existing.bottleneck_id : 'BN-' + nowMs) : null;
const stateTxt = primary ? ('Discharge blocked: ' + primary.label + (blockers.length > 1 ? '; also ' + blockers.slice(1).map(b => b.label).join(', ') : '')) : '';

const partial = unavailable.length ? ('Data unavailable from: ' + unavailable.join(', ') + '. Report is partial; not assumed complete.') : '';
Object.assign(out, {
  status: 'success', write: !!primary,
  patient: { patient_id: patient.patient_id, patient_name: patient.patient_name, department: patient.department, bed_id: patient.bed_id },
  clearances: cl, blockers: blockers, primary: primary, agents: agents, partial_data_note: partial,
  minutes_past_planned: minsPast,
  bn_mode: primary ? (existing ? 'update' : 'insert') : 'none',
  bottleneck: primary ? {
    bottleneck_id: bnId, affected: patient.patient_id, department: primary.key === 'clinical' || primary.key === 'summary' ? patient.department : primary.owner,
    current_state: stateTxt, start_time: existing ? existing.start_time : nowIso,
    duration_minutes: existing && existing.start_time ? Math.max(0, Math.round((nowMs - new Date(existing.start_time).getTime()) / 60000)) : Math.max(0, minsPast || 0),
    root_cause: primary.label + ' (' + (cl[primary.key] || '') + ')', dependency: blockers.map(b => b.key).concat(['discharge']).join(' -> '),
    owner: primary.owner, impact_patients: 1, severity: (minsPast !== null && minsPast > 120) ? 'high' : 'medium',
    suggested_action: primary.action, status: 'open'
  } : null,
  notification: primary ? {
    notification_id: 'NTF-' + nowMs, created_at_ts: nowIso, recipient_type: 'staff', recipient_ref: ownerRef, channel: 'in_app',
    message: 'Discharge blocker for ' + patient.patient_name + ' (' + patient.patient_id + '): ' + primary.label + '. ' + primary.action + '.',
    source_agent: 'discharge_agent', severity: (minsPast !== null && minsPast > 120) ? 'high' : 'medium', status: 'sent'
  } : null
});
return finish();

const a = $('Aggregate Discharge Analysis').first().json;
const r = a.req;
const base = { log_time: new Date().toISOString(), task_id: r.task_id, user_role: r.user_role, user_ref: r.user_ref, request: r.request_text || ('discharge analysis ' + r.patient_id), patient_id: r.patient_id };
const rows = [];
if (a.status !== 'success') {
  rows.push(Object.assign({}, base, { from_agent: 'careos_orchestrator', to_agent: 'discharge_agent', action: 'analyze_discharge', system: 'careos_data_layer', result_status: a.status, result_summary: String(a.reason).slice(0, 480) }));
} else {
  (a.agents || []).forEach(g => rows.push(Object.assign({}, base, { from_agent: 'careos_orchestrator', to_agent: g.agent, action: 'discharge_dependency_check', system: g.system, result_status: g.status, result_summary: String(g.note).slice(0, 480) })));
  rows.push(Object.assign({}, base, { from_agent: 'careos_orchestrator', to_agent: 'discharge_agent', action: 'analyze_discharge', system: 'careos_data_layer', result_status: 'success', result_summary: a.primary ? ('primary blocker: ' + a.primary.label + '; owner ' + a.primary.owner) : 'no blockers found' }));
  if (a.write) {
    rows.push(Object.assign({}, base, { from_agent: 'discharge_agent', to_agent: 'bottleneck_agent', action: a.bn_mode === 'update' ? 'update_bottleneck' : 'create_bottleneck', system: 'careos_data_layer', result_status: 'success', result_summary: a.bottleneck.bottleneck_id + ' ' + a.bottleneck.current_state }));
    rows.push(Object.assign({}, base, { from_agent: 'discharge_agent', to_agent: 'notification', action: 'send_notification', system: 'careos_data_layer', result_status: 'success', result_summary: 'notified ' + a.notification.recipient_ref }));
  }
}
return rows.map(j => ({ json: j }));

const a = $('Aggregate Discharge Analysis').first().json;
const r = a.req;
let result;
if (a.status !== 'success') {
  result = { patient_id: r.patient_id, message: a.reason, action_note: 'No automatic clinical or financial action taken' };
} else {
  result = {
    patient_id: a.patient.patient_id,
    patient_name: a.patient.patient_name,
    clearances: a.clearances,
    primary_blocker: a.primary ? a.primary.label : 'none - all discharge dependencies clear',
    secondary_blockers: a.blockers.slice(1).map(b => b.label),
    owner: a.primary ? a.primary.owner : null,
    recommended_action: a.primary ? a.primary.action : 'Proceed with discharge per protocol',
    agents_consulted: a.agents.map(g => g.agent + ' (' + g.status + ')'),
    bottleneck_id: a.bottleneck ? a.bottleneck.bottleneck_id : null,
    minutes_past_planned_discharge: a.minutes_past_planned,
    partial_data_note: a.partial_data_note,
    action_note: 'No automatic clinical or financial action taken'
  };
}
return [{ json: { task_id: r.task_id, agent: 'discharge_agent', status: a.status, result: result, _channel: r.channel } }];
